{
 header('Cache-Control: no-store');
 try{
  sx_start();$prefix='';$entity=1;$pdo=connect_store_common($prefix,$entity);ygo_news_schema($pdo);$_SESSION['news_token']??=bin2hex(random_bytes(24));
